import 'package:mysql_client_plus/mysql_client_plus.dart'; void main() async { final conn = await MySQLConnection.createConnection(host: 'localhost', port: 3306, userName: 'root', password: '', databaseName: 'pos_desktop'); await conn.connect(); final res = await conn.execute('SELECT id, user_id, display_name, employee_code FROM employee_profile'); for (var row in res.rows) { print(row.assoc()); } final res2 = await conn.execute('SELECT id, username FROM user'); for (var row in res2.rows) { print(row.assoc()); } await conn.close(); }
